export function InspirationRemark(prop: HoverRemarkProp) {
  return (
    <ReferIntoroRemarkFrame {...prop} maxContentHeight='calc(50dvh - 1em)'>
      冒頭の紹介で触れているように、発想やひらめきには『結びつける』ことが意外と大切だと個人的に考えています。<br/>
      <br/>
      そして、何かを考えて込んでいる状態の時に、まったく別の分野を関連付けて結びつけれるのは、色々な事に興味を持って、その仕組みを大まかに捉えているからこそだと思われます。<br/>
      (興味がないとまず仕組みに目がいかず、間接的な情報から思い出せるほど記憶にも残らないですし)<br/>
      <br/>
      これはChatGPTやGeminiのようなAIを使って発想を得ようとする際も同様で、AIに対して的確な指示(プロンプト)を出せるかにも影響してきそうです。<br/>
      <br/>
      <Box border='1px solid rgb(0 0 0 / 0.3)' m='0.5em' p='0.5em 1em 0.5em 1em'>
        <AiMethod />
      </Box>
    </ReferIntoroRemarkFrame>
  )
}


export function AiRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      <AiMethod />
    </HoverRemark>
  )
}

function AiMethod() {
  return (
    <>
      ChatGPTやGeminiは、「答えをくれる先生・専門家」と勘違いされがちですが、「素人だけど、すごい量の情報を調べて答えを推測してくれる働き者」といった感じかと。<br/>
      そのため、こちらが漠然とした曖昧な指示(質問)をすると、"もっともらしいけど専門家からしたら間違った(もしくはイマイチな)解答"をします。<br/>
      (まるで『上司がよく解ってないことを部下へ曖昧に指示して、部下は混乱しながらも一生懸命調べた結果をそれっぽく報告する』みたいで、人間臭く感じるところが面白いです)<br/>
      <br/>
      まぁ、AIは専門家でも実経験者でもないですし、上の『上司の例』を考えると、「曖昧な指示を出す方が悪い」と納得してもらえるかと。<br/>
      <br/>
      なので、ChatGPTやGeminiに聞く場合も、部下に指示を出す上司のように、まず何処までの答えを出して欲しいのか、どういった方法での答えが欲しいのかを、
      AIとの会話を通して明確に指示を出していく必要があります。<br/>
      (指示の的確さで、返される成果も大きく変わります)<br/>
      <br/>
      「AIに聞けば良い」でなく、この『指示を考える』能力が必要になります。(AIという『よい働き者』を潰す上司にならないために)
    </>
  )
}

export function TipaRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      かけた時間に対する効果のこと。<br/>
      <MyLink href='https://ja.wikipedia.org/wiki/タイムパフォーマンス'>タイムパフォーマンス：Wikipedia</MyLink><br/>
      <br/>
      もとはビジネスにおける時間と能率の関係についての用語で、<br/>
      <Box border='1px solid rgb(0 0 0 / 0.3)' m='0.5em' p='0.5em 1em 0.5em 1em'>
        中長期的な経営方針から事業の損得(優先事業)を選定、優先とされた事業の目標達成に"限られた時間資源"を集中させるため、その他事業の作業時間を効率化・短縮することに努めるスタンス(姿勢)
      </Box>
      を指す言葉かと思います。<br/>
      <br/>
      ただ、ビジネスでなく個人の行動にもこの言葉が当てはめられるようになって、"何のために効率化するのか" が薄れたように感じています。<br/>
      中長期的な方針も、それに伴う優先の選定もなく、その場の感情で"やりたくない"ことを早く済ませつつ、それっぽい結果を得るか。といった具合に。<br/>
      <br/>
      その流れから、「失敗したら費やした時間が無駄」と "失敗を避ける" ような行動にもタイパの言葉が当てはめられたのかな〜 と思っています。<br/>
      <br/>
      <Box>
        私の好きな言葉に<MyLink href='https://kotobank.jp/word/人間万事塞翁が馬-593690#mainTitle'>『人間万事塞翁が馬』</MyLink>があるのですが、<br/>
      </Box>
      "失敗"は誰でも嫌なものです。でも、やりたい目標に向かってチャレンジした結果の"失敗"は、意外と経験として他の分野で活きたりするので、"無駄"と判断するのは難しいかと。<br/>
      <br/>
      <Remarks mark='※'>
        肯定的にも批判的にも使われる言葉ですが、とかく若い世代を揶揄するように使われるのをよく見かけます。<br/>
        ただ、そうやって言葉で分類して型にはめている我々中高老年世代も、形は違うものの同じ課題を抱えていそうです。(若い世代は自分たち中高老年世代を写す鏡なだけなのかもしれません)
      </Remarks>
    </HoverRemark>
  )
}


type ReferIntoroRemarkFrameProp = HoverRemarkProp & {
  children: ReactNode;
}
export function ReferIntoroRemarkFrame(prop: ReferIntoroRemarkFrameProp) {
  const { children, ...remarkProp } = prop;
  return (
    <HoverRemark {...remarkProp}>
      {children}
      <br/>
      メニューバーのアイコンをクリックすると、冒頭の紹介が再表示されるので、興味がでたら見てみてください。<br/>
      <Image src={titleIcon} w='10em' aspectRatio='151 / 65' loading='lazy' />
    </HoverRemark>
  )
}


