import { useState } from 'react'
import type { ReactNode, MouseEventHandler } from 'react'

import { HoverCard, Link, Portal } from '@chakra-ui/react'
//import type { HoverCardProps } from '@chakra-ui/react'
//import type { PositioningOptions } from '@zag-js/popper' @floating-ui/react-dom でも良いかも
import type { Boundary } from '@floating-ui/dom'

import { MyScrollArea } from '~/ui/parts/MyScrollArea'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


export type HoverRemarkProp = {
  withinPortal?: boolean;
  withinScroll?: boolean;
  maxContentHeight?: string;
}
type Prop = HoverRemarkProp & {
  children: ReactNode;
}
export function HoverRemark(prop: Prop) {
  const { children, withinPortal = false, withinScroll = false, maxContentHeight } = prop;
  const [ open, setOpen ] = useState<boolean>(false);
  
  const clickHandler: MouseEventHandler<HTMLButtonElement> = (event) => {
    event.stopPropagation();
    setOpen((oldOpen) => (oldOpen) ? !oldOpen : oldOpen);
  }
  // type PositioningOptions
  const positioning = withinScroll ? {
    // scroll内では、そのScrollの領域にHoverを表示する
    // https://floating-ui.com/docs/usefloating
    slide: true, boundary: 'clippingParents' as Boundary, adaptive: true
  } : {
    slide: true
  };
  
  return (
    <HoverCard.Root 
      open={open} onOpenChange={(e) => setOpen(e.open)}
      positioning={positioning}
      >
      <HoverCard.Trigger asChild onClick={clickHandler}>
        <Link href="#" css={styles.mark}>(*)</Link>
      </HoverCard.Trigger>
      <Portal disabled={withinPortal}>
        <HoverCard.Positioner>
          {/* scroll内にいる際は、親スクロールViewPortの高さ(chakra UIは--heightに)をmaxとする */}
          <HoverCard.Content maxWidth={withinScroll ? 'var(--width)' : 'unset'} w='min(40em, 70svw)'
            maxHeight={withinScroll ? 'var(--height)' : maxContentHeight}
            >
            <HoverCard.Arrow />
            <MyScrollArea.Normal>
              {children}
            </MyScrollArea.Normal>
          </HoverCard.Content>
        </HoverCard.Positioner>
      </Portal>
    </HoverCard.Root>
  )
}




const styles = {
  mark: css`
    font-size: 0.8em;
    vertical-align: top;
    color: inherit;
  `
}

